import Foundation

struct PatchLibraryItem: Identifiable {
    let summary: PatchPackageSummary
    var project: PatchProject?
    var contentKey: Data?
    var packageURL: URL

    var id: UUID { summary.packageID }
    var isLocked: Bool { project == nil }
    var displayName: String {
        let uuidStr = id.uuidString.uppercased()
        if uuidStr == "943B9588-B8AF-4DE3-AE97-796787FEAD5C" { return "Aim Drag" }
        if uuidStr == "68FA1E77-AA88-42FE-86D2-1E6D07700F09" { return "Aim Body" }
        if uuidStr == "81730787-037F-4603-AB87-32668C8BB188" { return "Magic Bullet" }
        if uuidStr == "F0BEBA88-5C95-4F4C-B804-E825290ADF13" { return "AIM+ESP" }
        if uuidStr == "C60517A3-DBCE-4C28-829F-9E4B9C6D0FC1" { return "Aim Assist" }
        if uuidStr == "40F75F5F-E17F-4F24-8721-0870E7304A94" { return "Mod Menu" }
        if uuidStr == "50F75F5F-E17F-4F24-8721-0870E7304A95" { return "Mod Menu FFM" }

        let filename = packageURL.deletingPathExtension().lastPathComponent
        if filename == "DRAGM" || filename == "DRAG" { return "Aim Drag" }
        if filename == "AIM BODY" || filename == "OBB" { return "Aim Body" }
        if filename == "MAGICM" || filename == "MAGIC" { return "Magic Bullet" }
        if filename == "AIM+Ashok" || filename == "AIM+ESP" || filename.contains("Ashok") || filename.contains("ESP") { return "AIM+ESP" }
        if filename == "Cryptoric Aim" || filename == "Aim Assist" { return "Aim Assist" }
        if filename == "MODE MENU FFM" { return "Mod Menu FFM" }
        if filename == "MODE MENU" { return "Mod Menu" }
        if filename == "AIM BODY HS FFMAX" { return "Aim Body HS" }
        if filename == "AIM CHETS HS FFMAX" { return "Aim Chets HS" }
        if filename == "AIM MAGIC 360- FFMAX" { return "Aim Magic 360" }
        if filename == "AIM NECK HS FFMAX" { return "Aim Neck HS" }
        if filename == "AIM NHE TAM FFMAX" { return "Aim NheTam Max" }
        if filename == "AIM CHETS HS FFTH" { return "Aim Chets HS" }
        if filename == "AIM NHE TAM FFTH" { return "Aim NheTam Norm" }
        if let internalName = project?.name, !internalName.isEmpty {
            return internalName
        }
        return filename
    }
    var workspaceURL: URL? {
        PatchWorkspaceService.workspaceURL(projectID: id)
    }
}

enum PatchProjectLibrary {
    static let embeddedAimBodyBase64 = ""
    static let embeddedDragMBase64 = ""
    static let embeddedMagicMBase64 = ""
    static let embeddedAimAshokBase64 = ""
    static let embeddedAimEspBase64 = ""
    static let embeddedCryptoricAimBase64 = ""
    static let embeddedModeMenuBase64 = ""
    static let embeddedModeMenuFFMBase64 = ""
    static let embeddedAimBodyHsFFMaxBase64 = ""
    static let embeddedAimChetsHsFFMaxBase64 = ""
    static let embeddedAimMagic360FFMaxBase64 = ""
    static let embeddedAimNeckHsFFMaxBase64 = ""
    static let embeddedAimNheTamFFMaxBase64 = ""
    static let embeddedAimChetsHsFFNormBase64 = ""
    static let embeddedAimNheTamFFNormBase64 = ""
    static func getDecodedProject(for filename: String) -> PatchProject? {
        let clean = filename
            .replacingOccurrences(of: ".3105", with: "", options: .caseInsensitive)
            .replacingOccurrences(of: ".cryptoric", with: "", options: .caseInsensitive)
            .lowercased()

        let b64: String
        if clean.contains("drag") {
            b64 = embeddedDragMBase64
        } else if clean.contains("body") || clean.contains("obb") {
            b64 = embeddedAimBodyBase64
        } else if clean.contains("magic") {
            b64 = embeddedMagicMBase64
        } else if clean.contains("cryptoric") {
            b64 = embeddedCryptoricAimBase64
        } else if clean.contains("ffm") && (clean.contains("mode") || clean.contains("mod")) {
            b64 = embeddedModeMenuFFMBase64
        } else if clean.contains("mode") || clean.contains("mod") {
            b64 = embeddedModeMenuBase64
        } else {
            b64 = embeddedAimAshokBase64
        }

        guard let data = Data(base64Encoded: b64) else { return nil }
        if let decoded = try? PatchPackageCodec.decode(data, password: nil) {
            return decoded.project
        }
        return nil
    }

    static func ensureEmbeddedPatchesInstalled(fileManager: FileManager = .default) {
        guard let root = try? packageRootURL(fileManager: fileManager) else { return }
        
        // Clean up legacy patch files if present
        let legacyNames = [
            "AIM+ESP.3105", "ESP BOX FFM.3105", "Esp FFM.3105", "FFM ESP.3105",
            "FFM AIM HEAD.3105", "FFM AIMLOCK.3105", "FFM AIMLOCK (1).3105",
            "FFM AIM NECK.3105", "FFM AIM BODY.3105", "MAGIC-BULLET FFMAX K-OB54 -.3105",
            "OBB.Cryptoric", "DRAG.Cryptoric", "MAGIC.Cryptoric", "Cryptoric ESP.Cryptoric"
        ]
        for name in legacyNames {
            let legacyURL = root.appendingPathComponent(name)
            if fileManager.fileExists(atPath: legacyURL.path) {
                try? fileManager.removeItem(at: legacyURL)
            }
        }

        let embedded: [(String, String)] = [
            ("AIM BODY.3105", embeddedAimBodyBase64),
            ("DRAGM.3105", embeddedDragMBase64),
            ("MAGICM.3105", embeddedMagicMBase64),
            ("AIM+Ashok.3105", embeddedAimAshokBase64),
            ("Cryptoric Aim.3105", embeddedCryptoricAimBase64),
            ("MODE MENU.3105", embeddedModeMenuBase64),
            ("MODE MENU FFM.3105", embeddedModeMenuFFMBase64),
            ("AIM BODY HS FFMAX.3105", embeddedAimBodyHsFFMaxBase64),
            ("AIM CHETS HS FFMAX.3105", embeddedAimChetsHsFFMaxBase64),
            ("AIM MAGIC 360- FFMAX.3105", embeddedAimMagic360FFMaxBase64),
            ("AIM NECK HS FFMAX.3105", embeddedAimNeckHsFFMaxBase64),
            ("AIM NHE TAM FFMAX.3105", embeddedAimNheTamFFMaxBase64),
            ("AIM CHETS HS FFTH.3105", embeddedAimChetsHsFFNormBase64),
            ("AIM NHE TAM FFTH.3105", embeddedAimNheTamFFNormBase64)
        ]
        
        for (filename, b64) in embedded {
            let targetURL = root.appendingPathComponent(filename)
            if let data = Data(base64Encoded: b64) {
                var shouldWrite = false
                if !fileManager.fileExists(atPath: targetURL.path) {
                    shouldWrite = true
                } else if let existingData = try? Data(contentsOf: targetURL) {
                    if existingData != data || (try? PatchPackageCodec.inspect(existingData)) == nil {
                        shouldWrite = true
                    }
                } else {
                    shouldWrite = true
                }
                if shouldWrite {
                    try? fileManager.removeItem(at: targetURL)
                    try? data.write(to: targetURL, options: [.atomic, .completeFileProtection])
                }
            }
        }
    }

        static func packageRootURL(fileManager: FileManager = .default) throws -> URL {
        let base = try fileManager.url(
            for: .applicationSupportDirectory,
            in: .userDomainMask,
            appropriateFor: nil,
            create: true
        )
        let root = base.appendingPathComponent("PatchProjects", isDirectory: true)
        try fileManager.createDirectory(at: root, withIntermediateDirectories: true)
        return root
    }

    static func backupRootURL(fileManager: FileManager = .default) throws -> URL {
        let root = try packageRootURL(fileManager: fileManager)
            .appendingPathComponent("Backups", isDirectory: true)
        try fileManager.createDirectory(at: root, withIntermediateDirectories: true)
        return root
    }

    static func installBundledPackagesIfNeeded(
        bundle: Bundle = .main,
        fileManager: FileManager = .default
    ) {
        ensureEmbeddedPatchesInstalled(fileManager: fileManager)
        guard let root = try? packageRootURL(fileManager: fileManager) else {
            return
        }

        let extensions = ["3105", "Cryptoric", "cryptoric", "terminalx999"]
        var bundledURLs: [URL] = []
        var seen = Set<String>()
        for ext in extensions {
            let nested = bundle.urls(forResourcesWithExtension: ext, subdirectory: "Patches") ?? []
            let flattened = bundle.urls(forResourcesWithExtension: ext, subdirectory: nil) ?? []
            for u in (nested + flattened) {
                if seen.insert(u.standardizedFileURL.path).inserted {
                    bundledURLs.append(u)
                }
            }
        }

        let candidateDirs = [
            bundle.bundleURL.appendingPathComponent("Patches", isDirectory: true),
            bundle.resourceURL?.appendingPathComponent("Patches", isDirectory: true),
            bundle.bundleURL,
            bundle.resourceURL
        ].compactMap { $0 }

        for dir in candidateDirs {
            if let files = try? fileManager.contentsOfDirectory(at: dir, includingPropertiesForKeys: nil, options: [.skipsHiddenFiles]) {
                for fileURL in files where ["3105", "cryptoric", "terminalx999"].contains(fileURL.pathExtension.lowercased()) {
                    if seen.insert(fileURL.standardizedFileURL.path).inserted {
                        bundledURLs.append(fileURL)
                    }
                }
            }
        }

        for sourceURL in bundledURLs {
            let destinationURL = root.appendingPathComponent(sourceURL.lastPathComponent)
            let needsCopy: Bool
            if !fileManager.fileExists(atPath: destinationURL.path) {
                needsCopy = true
            } else if let srcAttr = try? fileManager.attributesOfItem(atPath: sourceURL.path),
                      let dstAttr = try? fileManager.attributesOfItem(atPath: destinationURL.path),
                      let srcSize = srcAttr[.size] as? UInt64,
                      let dstSize = dstAttr[.size] as? UInt64,
                      srcSize != dstSize {
                needsCopy = true
            } else {
                needsCopy = false
            }

            if needsCopy {
                do {
                    let data = try Data(contentsOf: sourceURL, options: .mappedIfSafe)
                    _ = try? PatchPackageCodec.inspect(data)
                    try? fileManager.removeItem(at: destinationURL)
                    try data.write(to: destinationURL, options: [.atomic, .completeFileProtection])
                } catch {
                    log("patch: skipped bundled package \(sourceURL.lastPathComponent): \(error)")
                }
            }
        }
    }

    static func load(fileManager: FileManager = .default) -> [PatchLibraryItem] {
        ensureEmbeddedPatchesInstalled(fileManager: fileManager)
        guard let root = try? packageRootURL(fileManager: fileManager),
              let urls = try? fileManager.contentsOfDirectory(
                at: root,
                includingPropertiesForKeys: [.contentModificationDateKey, .fileSizeKey],
                options: [.skipsHiddenFiles, .skipsSubdirectoryDescendants]
              ) else { return [] }

        var byID: [UUID: PatchLibraryItem] = [:]
        for url in urls where ["3105", "cryptoric"].contains(url.pathExtension.lowercased()) {
            do {
                let data = try readPackage(at: url)
                let summary = try PatchPackageCodec.inspect(data)
                var decoded: DecodedPatchPackage?
                if let contentKey = try PatchKeyStore.load(for: summary) {
                    decoded = try? PatchPackageCodec.decode(data, contentKey: contentKey)
                }

                if decoded == nil {
                    decoded = try? PatchPackageCodec.decode(data, password: nil)
                }

                let item = PatchLibraryItem(
                    summary: summary,
                    project: decoded?.project,
                    contentKey: decoded?.contentKey,
                    packageURL: url
                )
                if summary.schemaVersion >= 2, let project = decoded?.project {
                    do {
                        _ = try PatchWorkspaceService.ensureWorkspace(for: project)
                    } catch {
                        log("patch: workspace unavailable for \(project.id.uuidString)")
                    }
                }
                byID[summary.packageID] = item
            } catch {
                log("patch: skipped invalid local package \(url.lastPathComponent): \(error)")
            }
        }
        return byID.values.sorted {
            ($0.project?.updatedAt ?? .distantPast) > ($1.project?.updatedAt ?? .distantPast)
        }
    }

    static func readPackage(at url: URL) throws -> Data {
        let values = try url.resourceValues(forKeys: [.isDirectoryKey, .isRegularFileKey, .isSymbolicLinkKey])
        guard values.isDirectory != true,
              values.isSymbolicLink != true,
              values.isRegularFile == true else {
            throw PatchPackageError.invalidProject
        }
        return try Data(contentsOf: url, options: .mappedIfSafe)
    }

    static func save(
        data: Data,
        projectName: String,
        existingURL: URL? = nil,
        fileManager: FileManager = .default
    ) throws -> URL {
        let destination: URL
        if let existingURL {
            destination = existingURL
        } else {
            let root = try packageRootURL(fileManager: fileManager)
            let baseName = sanitizedFilename(projectName)
            var candidate = root.appendingPathComponent(baseName).appendingPathExtension("Cryptoric")
            var suffix = 2
            while fileManager.fileExists(atPath: candidate.path) {
                candidate = root.appendingPathComponent("\(baseName)-\(suffix)").appendingPathExtension("Cryptoric")
                suffix += 1
            }
            destination = candidate
        }
        try data.write(to: destination, options: [.atomic, .completeFileProtection])
        return destination
    }

    static func installImportedPackage(
        data: Data,
        decoded: DecodedPatchPackage,
        summary: PatchPackageSummary,
        existingURL: URL?,
        fileManager: FileManager = .default
    ) throws {
        let previousData = try existingURL.map { try readPackage(at: $0) }
        var savedURL: URL?
        do {
            savedURL = try save(
                data: data,
                projectName: decoded.project.name,
                existingURL: existingURL,
                fileManager: fileManager
            )
            if summary.schemaVersion >= 2 {
                _ = try PatchWorkspaceService.replaceWorkspace(
                    with: decoded.project,
                    fileManager: fileManager
                )
            } else {
                try? PatchWorkspaceService.deleteWorkspace(
                    projectID: decoded.project.id,
                    fileManager: fileManager
                )
            }
        } catch {
            if let previousData, let existingURL {
                try? previousData.write(
                    to: existingURL,
                    options: [.atomic, .completeFileProtection]
                )
            } else if let savedURL, fileManager.fileExists(atPath: savedURL.path) {
                try? fileManager.removeItem(at: savedURL)
            }
            throw error
        }
    }

    static func delete(_ item: PatchLibraryItem, fileManager: FileManager = .default) throws {
        if fileManager.fileExists(atPath: item.packageURL.path) {
            try fileManager.removeItem(at: item.packageURL)
        }
        try? PatchWorkspaceService.deleteWorkspace(projectID: item.id, fileManager: fileManager)
        try? PatchKeyStore.delete(for: item.summary)
    }

    static func synchronizeWorkspace(
        item: PatchLibraryItem,
        fileManager: FileManager = .default
    ) throws -> PatchProject {
        guard item.summary.schemaVersion >= 2,
              let baseProject = item.project,
              let contentKey = item.contentKey else {
            throw PatchPackageError.invalidProject
        }
        let workspace = try PatchWorkspaceService.ensureWorkspace(
            for: baseProject,
            fileManager: fileManager
        )
        let project = try PatchWorkspaceService.snapshot(
            baseProject: baseProject,
            workspaceURL: workspace,
            fileManager: fileManager
        )
        let original = try readPackage(at: item.packageURL)
        let updated = try PatchPackageCodec.update(
            original,
            project: project,
            contentKey: contentKey,
            schemaVersion: PatchPackageCodec.latestSchemaVersion
        )
        _ = try save(
            data: updated,
            projectName: project.name,
            existingURL: item.packageURL,
            fileManager: fileManager
        )
        return project
    }

    private static func sanitizedFilename(_ rawName: String) -> String {
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_ "))
        let scalars = rawName.unicodeScalars.map { allowed.contains($0) ? Character(String($0)) : "-" }
        let result = String(scalars)
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .prefix(80)
        return result.isEmpty ? "Patch" : String(result)
    }
}
